import{_ as e,o as n,c as s,a2 as t}from"./chunks/framework.CNDaxUod.js";const g=JSON.parse('{"title":"Distributed Tracing (OpenTelemetry & Jaeger)","description":"","frontmatter":{},"headers":[],"relativePath":"observability/tracing.md","filePath":"observability/tracing.md","lastUpdated":null}'),r={name:"observability/tracing.md"};function i(l,a,p,o,c,d){return n(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="distributed-tracing-opentelemetry-jaeger" tabindex="-1">Distributed Tracing (OpenTelemetry &amp; Jaeger) <a class="header-anchor" href="#distributed-tracing-opentelemetry-jaeger" aria-label="Permalink to &quot;Distributed Tracing (OpenTelemetry &amp; Jaeger)&quot;">​</a></h1><p>OpenFlow integrates the <strong>OpenTelemetry Go SDK</strong> with OTLP HTTP trace exporting directly to <strong>Jaeger</strong>.</p><hr><h2 id="_1-tracing-hierarchy" tabindex="-1">1. Tracing Hierarchy <a class="header-anchor" href="#_1-tracing-hierarchy" aria-label="Permalink to &quot;1. Tracing Hierarchy&quot;">​</a></h2><p>Every execution produces a structured span hierarchy:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ Root Span: Workflow: kafka-pipeline ]</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ├── [ Child Span: Stage: Validate Telemetry Payload (transform) ]</span></span>
<span class="line"><span>   ├── [ Child Span: Stage: Check Critical Threshold (exclusive_xor) ]</span></span>
<span class="line"><span>   └── [ Child Span: Stage: Archive Telemetry Record in DB (database) ]</span></span></code></pre></div><p>And for failed executions with Saga Rollbacks:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ Root Span: Workflow: financial-transfer-saga (Error) ]</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ├── [ Child Span: Stage: Deduct Sender (transform - OK) ]</span></span>
<span class="line"><span>   ├── [ Child Span: Stage: Credit Receiver (transform - OK) ]</span></span>
<span class="line"><span>   ├── [ Child Span: Stage: Publish Event (kafka - FAILED) ]</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ├── [ Child Span: Compensate: Revert Receiver Credit (transform - OK) ]</span></span>
<span class="line"><span>   └── [ Child Span: Compensate: Refund Sender Balance (transform - OK) ]</span></span></code></pre></div><hr><h2 id="_2-exploring-in-jaeger-ui" tabindex="-1">2. Exploring in Jaeger UI <a class="header-anchor" href="#_2-exploring-in-jaeger-ui" aria-label="Permalink to &quot;2. Exploring in Jaeger UI&quot;">​</a></h2><ol><li>Open Jaeger UI at <strong><a href="http://localhost:16686" target="_blank" rel="noreferrer">http://localhost:16686</a></strong>.</li><li>Under <strong>Service</strong>, select <code>openflow-orchestrator</code>.</li><li>Click <strong>Find Traces</strong> to view the timeline, latencies, and span tags.</li></ol>`,11)])])}const u=e(r,[["render",i]]);export{g as __pageData,u as default};
